import 'dart:async'; import 'dart:typed_data'; import 'package:flutter/foundation.dart'; import 'package:flutter/material.dart'; import 'package:go_router/go_router.dart'; import 'package:printing/printing.dart'; import 'package:pdf/widgets.dart' as pw; import '../../theme.dart'; import '../../nav.dart'; import 'dashboard_ui.dart'; import 'dashboard_editors.dart';
String _truncate(String v, int max) { final s=v.trim(); if(s.length<=max) return s; return '${s.substring(0,max).trim()}…'; }

// PDF en ISOLATE - ne bloque jamais le UI thread même à 1M users
Future<Uint8List> _buildCvPdfIsolate(Map<String, dynamic> data) async { final doc=pw.Document(); final theme=pw.ThemeData.withFont(); doc.addPage(pw.MultiPage(theme: theme, build: (_)=> [pw.Text('THIX ID — ${data['displayName']}', style: pw.TextStyle(fontSize: 18, fontWeight: pw.FontWeight.bold)), pw.SizedBox(height: 8), pw.Text(data['thixId']??''), pw.SizedBox(height: 10), pw.Text('Bio', style: pw.TextStyle(fontWeight: pw.FontWeight.bold)), pw.Text(data['bio']??'—'), pw.SizedBox(height: 12), pw.Text('Expériences', style: pw.TextStyle(fontWeight: pw.FontWeight.bold)),...((data['experience'] as List).map((e)=> pw.Bullet(text: '${e['title']??''} • ${e['org']??''}')))])); return doc.save(); }

class ProfileTab extends StatelessWidget { final dynamic authUser, profile; final int score; final dynamic profileService; const ProfileTab({super.key, required this.authUser, required this.profile, required this.score, required this.profileService}); @override Widget build(BuildContext context) { final user=profile; final isActivated = authUser.thixId.toString().toUpperCase()!= 'THIX-PENDING'; return TabScaffold(children: [ if(!isActivated &&!(authUser.hasActiveTrial??false)) ActivationCalloutCard(onActivate: (){ final r=Uri.encodeComponent(AppRoutes.activationReceipt); context.go('${AppRoutes.payment}?returnTo=$r'); }), DashboardCard(icon: Icons.badge_rounded, title: 'Profil Professionnel', subtitle: 'Données sécurisées', child: Column(children: [ DashboardInfoRow(label: 'THIX ID', value: user.thixId), DashboardInfoRow(label: 'Email', value: authUser.email??'—'), DashboardInfoRow(label: 'Téléphone', value: authUser.phone??'—'), DashboardInfoRow(label: 'Profession', value: user.occupation??'—'), const SizedBox(height: 8), Row(children: [ Expanded(child: _ExpandableTextRow(label: 'Bio', text: user.bio??'—')), const SizedBox(width: 8), _VisibilityToggle(label: 'Public', value: user.visibility.bio, onChanged: (v)=> profileService.updateVisibility(userId: user.userId, visibility: user.visibility.copyWith(bio: v))) ]) ])), DashboardCard(icon: Icons.school_rounded, title: 'Cursus ${user.education.length}', subtitle: 'Formations', child: Column(children: user.education.isEmpty? [const Text('Aucune formation', style: TextStyle(color: Colors.grey, fontSize: 12))] : user.education.take(3).map<Widget>((e)=> ListTile(dense:true, contentPadding: EdgeInsets.zero, title: Text(e['institution']??'—', style: const TextStyle(fontWeight: FontWeight.w700, fontSize: 13)), subtitle: Text('${e['degree']??''} • ${e['city']??''}', style: const TextStyle(fontSize: 11, color: Colors.grey)))).toList())), ]); } }
class _VisibilityToggle extends StatelessWidget { final String label; final bool value; final ValueChanged<bool>? onChanged; final String? tooltip; const _VisibilityToggle({required this.label, required this.value, required this.onChanged, this.tooltip}); @override Widget build(BuildContext context) { final w=Row(mainAxisSize: MainAxisSize.min, children: [Text(label, style: const TextStyle(fontSize: 11, color: Colors.grey, fontWeight: FontWeight.w700)), const SizedBox(width: 6), Switch(value: value, onChanged: onChanged, activeColor: Colors.green, materialTapTargetSize: MaterialTapTargetSize.shrinkWrap)]); return tooltip==null? w : Tooltip(message: tooltip!, child: w); } }
class _ExpandableTextRow extends StatefulWidget { final String label, text; const _ExpandableTextRow({required this.label, required this.text}); @override State<_ExpandableTextRow> createState()=> _ExpandableTextRowState(); }
class _ExpandableTextRowState extends State<_ExpandableTextRow> { bool exp=false; @override Widget build(BuildContext context) { final t=widget.text.trim().isEmpty?'—':widget.text.trim(); return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [ Row(children: [Text(widget.label, style: const TextStyle(fontSize: 11, color: Colors.grey, fontWeight: FontWeight.w700)), const Spacer(), GestureDetector(onTap: t=='—'?null:()=> setState(()=> exp=!exp), child: Text(exp?'Voir moins':'Voir plus', style: const TextStyle(fontSize: 11, color: Color(0xFF123B7A), fontWeight: FontWeight.w700)))]), const SizedBox(height: 4), Text(t, maxLines: exp?99:3, overflow: TextOverflow.ellipsis, style: const TextStyle(fontSize: 13, height: 1.35)) ]); } }

class DocumentsTab extends StatefulWidget { final String uid; final dynamic docs, userService; final String filter; final ValueChanged<String> onChangeFilter; const DocumentsTab({super.key, required this.uid, required this.docs, required this.userService, required this.filter, required this.onChangeFilter}); @override State<DocumentsTab> createState()=> _DocumentsTabState(); }
class _DocumentsTabState extends State<DocumentsTab> { final _scrollCtrl=ScrollController(); static const _pageSize=20; int _visibleCount=20; @override void dispose(){ _scrollCtrl.dispose(); super.dispose(); } @override Widget build(BuildContext context) => TabScaffold(children: [ DashboardCard(icon: Icons.folder_special_rounded, title: 'Documents', subtitle: 'Portefeuille sécurisé', child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [ Wrap(spacing: 6, runSpacing: 6, children: ['Tous','CIN','Passeport','Permis','Diplôme','Autre'].map((f)=> ChoiceChip(label: Text(f, style: const TextStyle(fontSize: 11)), selected: widget.filter==f, onSelected: (_){ setState(()=> _visibleCount=_pageSize); widget.onChangeFilter(f); }, selectedColor: LightModeColors.accent.withOpacity(0.18))).toList()), const SizedBox(height: 12), StreamBuilder<List<Map<String,dynamic>>>(stream: widget.docs.streamDocuments(widget.uid).handleError((_)=> []), builder: (context,snap){ if(snap.connectionState==ConnectionState.waiting) return const LinearProgressIndicator(minHeight: 2); final all=snap.data??[]; final filtered=all.where((d){ if(widget.filter=='Tous') return true; return (d['doc_type']??'Autre')==widget.filter; }).toList(); if(filtered.isEmpty) return const Padding(padding: EdgeInsets.symmetric(vertical: 20), child: Text('Aucun document', textAlign: TextAlign.center, style: TextStyle(color: Colors.grey))); final visible=filtered.take(_visibleCount).toList(); return Column(children: [...visible.map((d){ final title=d['title']??d['doc_id']??'Document'; final status=d['status']??'pending'; final chip=_DocStatusChip.from(status); return DocRow(name: title, date: d['doc_id']??'—', status: chip.label, statusBg: chip.bg, statusText: chip.fg); }), if(filtered.length>_visibleCount) TextButton(onPressed: ()=> setState(()=> _visibleCount+=_pageSize), child: Text('Voir plus (${filtered.length-_visibleCount} restants)')) ]); }), const SizedBox(height: 12), SizedBox(height: 48, child: ElevatedButton.icon(onPressed: () async { final ok=await ConfirmFeeSheet.show(context, title: 'Uploader document', description: 'Frais: 1 USD (simulation)', amountLabel: 'Payer 1 USD'); if(ok!=true) return; try{ await widget.userService.addPaymentTransaction(uid: widget.uid, title: 'Dépôt document', amount: 1, currency: 'USD', method: 'Simulé', status: 'paid'); } catch(_){} if(mounted) context.push(AppRoutes.vault); }, icon: const Icon(Icons.upload_rounded, color: Color(0xFF123B7A), size: 18), label: const Text('Uploader (1 USD)', style: TextStyle(color: Color(0xFF123B7A), fontWeight: FontWeight.w900, fontSize: 12)), style: ElevatedButton.styleFrom(backgroundColor: LightModeColors.accent, shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(30)))))])) ]); }
class _DocStatusChip { final String label; final Color bg, fg; const _DocStatusChip({required this.label, required this.bg, required this.fg}); factory _DocStatusChip.from(String raw){ final v=raw.trim().toLowerCase(); if(v=='verified') return _DocStatusChip(label: 'Vérifié', bg: const Color(0xFFE6FFFA), fg: Colors.green.shade700); if(v=='rejected') return _DocStatusChip(label: 'Rejeté', bg: Colors.red.shade50, fg: Colors.red.shade700); return _DocStatusChip(label: 'En attente', bg: LightModeColors.accent.withOpacity(0.15), fg: const Color(0xFF8A6B00)); } }

