class _CvTabState extends State<CvTab> { bool _exp=false; @override Widget build(BuildContext context) => TabScaffold(children: [ DashboardCard(icon: Icons.description_rounded, title: 'CV Numérique', subtitle: 'Généré depuis profil', child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [ Container(padding: const EdgeInsets.all(14), decoration: BoxDecoration(color: const Color(0xFFF8F8F8), borderRadius: BorderRadius.circular(12), border: Border.all(color: const Color(0xFFEAEAEA))), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text(widget.user.displayName, style: const TextStyle(fontWeight: FontWeight.w900, fontSize: 16)), Text(widget.user.thixId, style: const TextStyle(fontSize: 11, color: Colors.grey)), const SizedBox(height: 8), Text((widget.user.bio??'').toString().trim().isEmpty?'Bio non renseignée':widget.user.bio, maxLines: 4, overflow: TextOverflow.ellipsis, style: const TextStyle(fontSize: 12, height: 1.4))])), const SizedBox(height: 16), SizedBox(height: 52, child: ElevatedButton.icon(onPressed: _exp?null:() async { setState(()=> _exp=true); try{ final bytes=await compute(_buildCvPdfIsolate, {'displayName': widget.user.displayName, 'thixId': widget.user.thixId, 'bio': widget.user.bio??'—', 'experience': widget.user.experience??[]}); if(!mounted) return; await Printing.layoutPdf(onLayout: (_) async => bytes); } catch(e){ debugPrint('PDF error $e'); if(mounted) ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Export PDF impossible'))); } finally{ if(mounted) setState(()=> _exp=false); } }, icon: _exp? const SizedBox(width: 18, height: 18, child: CircularProgressIndicator(strokeWidth: 2.5, color: Color(0xFF123B7A))) : const Icon(Icons.download_rounded, color: Color(0xFF123B7A)), label: Text(_exp?'Génération...':'Télécharger CV PDF', style: const TextStyle(color: Color(0xFF123B7A), fontWeight: FontWeight.w900)), style: ElevatedButton.styleFrom(backgroundColor: LightModeColors.accent, shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(30))))), const SizedBox(height: 8), const Text('Généré en isolate - ne bloque pas l\'UI même à 1M users', textAlign: TextAlign.center, style: TextStyle(fontSize: 10, color: Colors.grey)) ]); }

class PaymentsTab extends StatelessWidget { final String uid; final dynamic userService, user; const PaymentsTab({super.key, required this.uid, required this.userService, required this.user}); @override Widget build(BuildContext context) => TabScaffold(children: [ DashboardCard(icon: Icons.payments_rounded, title: 'Paiements', subtitle: 'Historique transactions', child: StreamBuilder<List<Map<String,dynamic>>>(stream: userService.streamPayments(uid).handleError((_)=> []), builder: (context,snap){ if(snap.connectionState==ConnectionState.waiting) return const LinearProgressIndicator(minHeight: 2); final list=snap.data??[]; if(list.isEmpty) return const Padding(padding: EdgeInsets.all(20), child: Text('Aucune transaction', textAlign: TextAlign.center, style: TextStyle(color: Colors.grey))); return ListView.separated(shrinkWrap: true, physics: const NeverScrollableScrollPhysics(), itemCount: list.length.clamp(0,15), separatorBuilder: (_, __)=> const Divider(height: 1), itemBuilder: (_, i){ final d=list[i]; return ListTile(dense:true, contentPadding: EdgeInsets.zero, leading: Icon(d['status']=='paid'?Icons.check_circle:Icons.hourglass_bottom, color: d['status']=='paid'?Colors.green:Colors.orange, size: 20), title: Text(d['title']??'Transaction', style: const TextStyle(fontWeight: FontWeight.w700, fontSize: 13)), subtitle: Text('${d['created_at']??''} • ${d['method']??''}', style: const TextStyle(fontSize: 11, color: Colors.grey)), trailing: Text('${d['amount']??0} ${d['currency']??'USD'}', style: const TextStyle(fontWeight: FontWeight.w900, fontSize: 11))); }); })) ]); }
